export class WorkGesture135{
 constructor({act,preview=()=>{},progress=()=>{}}){Object.assign(this,{act,preview,progress});this.hold=null;}
 begin(hit,step,tool,x,y,id){if(!hit||!step||tool!==step.tool||hit.id!==step.target)return false;this.hold={hit,tool,x,y,id,elapsed:0,distance:0,done:false};this.preview(hit,tool,0);this.progress(0);return true;}
 move(x,y,id,valid=true,contact=null){const h=this.hold;if(!h||h.id!==id||h.done)return;if(!valid){this.cancel();return;}if(contact)h.hit=contact;const d=Math.hypot(x-h.x,y-h.y);h.x=x;h.y=y;if(h.tool==='brush'){h.distance+=Math.min(d,24);const t=Math.min(1,h.distance/110);this.preview(h.hit,h.tool,t);this.progress(t);if(t===1)this.commit();}}
 update(dt){const h=this.hold;if(!h||h.done||h.tool!=='driver')return;h.elapsed+=Math.max(0,Math.min(.05,dt));const t=Math.min(1,h.elapsed/.9);this.preview(h.hit,h.tool,t);this.progress(t);if(t===1)this.commit();}
 commit(){const h=this.hold;if(!h||h.done)return;h.done=true;this.act(h.hit.id);this.progress(0);}
 end(id){const h=this.hold;if(!h||h.id!==id)return false;if(!h.done)this.commit();this.hold=null;this.progress(0);return true;}
 cancel(){this.hold=null;this.progress(0);}
}
export class SubstationPlay135{
 constructor(ui){this.ui=ui;this.view=ui.view;this.doc=ui.doc;this.guided=true;const stage=this.view.canvas?.parentElement;if(!stage)return;
  this.hud=this.doc.createElement('section');this.hud.className='sr135-play';this.hud.setAttribute('aria-label','Objetivo de la práctica');this.hud.innerHTML='<div class="sr135-order"><span>ORDEN DE TRABAJO</span><b data-play135-count></b></div><h3 data-play135-title></h3><p data-play135-instruction></p><div class="sr135-track"><i data-play135-fill></i></div><button data-play135-focus>Enfocar pieza · F</button><label><input type="checkbox" data-play135-guide checked> Herramienta automática</label><div class="sr135-gesture" hidden><span data-play135-gesture-label></span><progress data-play135-gesture max="1" value="0"></progress></div>';stage.append(this.hud);this.hud.hidden=true;
  this.label=this.doc.createElement('output');this.label.className='sr135-contact';this.label.hidden=true;stage.append(this.label);
  this.hud.querySelector('[data-play135-guide]').addEventListener('change',e=>{this.guided=e.target.checked;});this.hud.querySelector('[data-play135-focus]').addEventListener('click',()=>this.focus());
  this.gesture=new WorkGesture135({act:id=>ui.act(id),preview:(hit,tool,p)=>{ui.showHand135(hit.target,tool,p,hit.point);},progress:p=>{const node=this.hud.querySelector('.sr135-gesture');node.hidden=!this.gesture?.hold||this.gesture.hold.done;this.hud.querySelector('[data-play135-gesture]').value=p;this.hud.querySelector('[data-play135-gesture-label]').textContent=this.gesture?.hold?.tool==='brush'?'Cepillado · arrastra el mouse':'Trabajo en curso';}});
  this.hud.querySelector('[data-play135-gesture-label]').textContent='Trabajo en curso';
  const c=this.view.canvas;c.setAttribute('tabindex','0');this.listen=(name,fn)=>c.addEventListener(name,fn,{capture:true});
  this.listen('pointerdown',e=>{if(!ui.active||ui.busy||e.button!==0||this.view.navigation.mode==='pan')return;const hit=this.pick(e);if(!hit)return;const step=ui.state.step;if(this.guided&&hit.id===step?.target){ui.state.choose(step.tool);ui.render();}if(!this.gesture.begin(hit,step,ui.state.tool,e.clientX,e.clientY,e.pointerId)){ui.act(hit.id);e.stopImmediatePropagation();e.preventDefault();return;}this.capture=e.pointerId;c.setPointerCapture?.(e.pointerId);this.controlsEnabled=this.view.controls.enabled;this.view.controls.enabled=false;c.focus?.({preventScroll:true});e.stopImmediatePropagation();e.preventDefault();});
  this.listen('pointermove',e=>{if(!ui.active||ui.busy)return;if(this.capture===e.pointerId){const hit=this.pick(e);this.gesture.move(e.clientX,e.clientY,e.pointerId,hit?.id===this.gesture.hold?.hit.id,hit);if(!this.gesture.hold)this.cancel();e.stopImmediatePropagation();e.preventDefault();return;}if(this.view.down||e.buttons||this.view.navigation.mode==='pan')return;const hit=this.pick(e);this.label.hidden=!hit;if(hit)this.label.textContent=(ui.state.mission.targets[hit.id]||hit.id)+' · '+(hit.id===ui.state.step?.target?'Objetivo actual':'Inspección');c.style.cursor=hit?'pointer':'';});
  this.listen('pointerup',e=>{if(this.capture!==e.pointerId)return;this.gesture.end(e.pointerId);this.release();e.stopImmediatePropagation();e.preventDefault();});for(const name of['pointercancel','lostpointercapture'])this.listen(name,()=>this.cancel());c.addEventListener('pointerleave',()=>{if(this.capture===undefined)this.label.hidden=true;});c.addEventListener('wheel',()=>this.cancel(),{capture:true});this.doc.addEventListener?.('visibilitychange',()=>{if(this.doc.hidden)this.cancel();});globalThis.addEventListener?.('blur',()=>this.cancel());c.addEventListener('keydown',e=>{if(!ui.active)return;if(e.key==='Escape'){this.cancel();ui.hand134?.hide();}if(e.key.toLowerCase()==='f'){e.preventDefault();this.focus();}});
 }
 pick(e){const v=this.view,r=v.canvas.getBoundingClientRect();v.camera.updateMatrixWorld(true);uiMatrix(this.ui);v.pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);v.ray.setFromCamera(v.pointer,v.camera);return this.ui.pick135(v.ray);}
 focus(){const target=this.ui.bench?.targets.get(this.ui.state.step?.target);if(target)this.view.focus(target);else if(this.ui.bench)this.view.focus(this.ui.bench.group);this.ui.hand134?.hide();}
 release(){const id=this.capture;this.capture=undefined;if(this.controlsEnabled!==undefined){this.view.controls.enabled=this.controlsEnabled;this.controlsEnabled=undefined;}if(id!==undefined&&this.view.canvas.hasPointerCapture?.(id))this.view.canvas.releasePointerCapture(id);}
 cancel(){this.gesture?.cancel();this.release();this.ui.hand134?.hide();if(this.label)this.label.hidden=true;}
 render(){if(!this.hud)return;const s=this.ui.state;this.hud.hidden=!this.ui.active;this.label.hidden=true;this.hud.dataset.complete=String(s.done);this.hud.querySelector('[data-play135-title]').textContent=s.done?'Intervención comprobada':s.mission.title;this.hud.querySelector('[data-play135-count]').textContent=s.done?'✓ COMPLETADA':Math.min(s.index+1,s.mission.steps.length)+' / '+s.mission.steps.length;this.hud.querySelector('[data-play135-instruction]').textContent=this.ui.busy?'Preparando banco 3D…':s.done?'Puedes repetir la práctica o elegir otra orden de trabajo.':s.step.text;this.hud.querySelector('[data-play135-fill]').style.width=(s.index/s.mission.steps.length*100)+'%';this.hud.querySelector('[data-play135-focus]').disabled=s.done||this.ui.busy;}
 update(dt){if(this.ui.active)this.gesture?.update(dt);}
}
function uiMatrix(ui){ui.bench?.group.updateMatrixWorld(true);}
